command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin work/physical-drag-start-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("physical-drag-start-final-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp a2750dd404eb57d88621138ddcc5e20daf122343
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 tools\winui\run_checks.py build --configuration Release
  if($LASTEXITCODE -ne 0){throw "Release build failed"}
  $env:FLY_MIGRATION_CONFIGURATION="Release"
  $env:FLY_M23_OWNED_FEATURES="YES"
  $env:FLY_M23_OWNED_DRAG_TEST="YES"
  $env:FLY_M23_OWNED_DRAG_TRACE="YES"
  & python -u tests\winui\test_shell_gui.py
  if($LASTEXITCODE -ne 0){throw "owned physical drag GUI failed"}
  Write-Host "PHYSICAL_DRAG_START_FIX=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
